export const GIVEN_SHA256 =
  "53c0d58ead24ee0b632533f5bb4d52e891fce0e540cd9d0e9dc00fcdf174685a";
export const SURNAMES_SHA256 =
  "3db1448be28e63a2ead8dbb356423675f162a63f0dd6fd85f4fdc8e90d2289c2";

function verify(list: readonly string[], expected: string, name: string): void {
  const actual = createHash("sha256").update(list.join("\n") + "\n", "utf8").digest("hex");
  if (actual !== expected) {
    throw new Error(`wordlist integrity check failed for ${name}: ${actual}`);
  }
}

verify(GIVEN, GIVEN_SHA256, "given-names-1024.txt");
verify(SURNAMES, SURNAMES_SHA256, "surnames-1024.txt");
